#include <bits/stdc++.h>
using namespace std;

class Solution {
public:
    bool isTransformable(string s, string t) {
        vector<queue<int>> pos(10);
        for (int i = 0; i < (int)s.size(); ++i) pos[s[i] - '0'].push(i);
        for (char ch : t) {
            int d = ch - '0';
            if (pos[d].empty()) return false;
            int idx = pos[d].front();
            for (int small = 0; small < d; ++small)
                if (!pos[small].empty() && pos[small].front() < idx)
                    return false;
            pos[d].pop();
        }
        return true;
    }
};
